// Package apiv1 is the relay's public admin API, generated from the OpenAPI
// description in /api/openapi.yaml (docs/internal/plans/admin-rest-api.md).
//
// apiv1.gen.go is generated by `make api` and must not be edited: change the
// description and regenerate. openapi.yaml here is a verbatim copy of the
// description, and openapi.json the same document as JSON; both are written
// by `make api` because Go cannot embed a file from outside its module, and
// both stay MPL-2.0 like the original (LICENSING.md). The relay serves them at
// /api/v1/openapi.yaml and /api/v1/openapi.json.
//
// The handlers live in package admin, which implements StrictServerInterface.
package apiv1

import _ "embed"

// SpecYAML is the API description as YAML.
//
//go:embed openapi.yaml
var SpecYAML []byte

// SpecJSON is the API description as JSON.
//
//go:embed openapi.json
var SpecJSON []byte
